renderTrips=redesignedTrips;
renderKnowledge=function(){oldKnowledge();app.querySelector('.heading .eyebrow').textContent='KIẾN THỨC CỦA DOANH NGHIỆP';app.querySelector('.heading p').textContent='Tài liệu, tour mẫu và kinh nghiệm để hỗ trợ AI xây phương án.';const bar=document.createElement('section');bar.className='knowledge-explainer';bar.innerHTML='<span class="knowledge-emblem">'+ico('book')+'</span><div><h2>Kinh nghiệm của đội ngũ, sẵn sàng để tái sử dụng.</h2><p>Tham khảo tài liệu khi tư vấn và tìm tour mẫu phù hợp với yêu cầu khách.</p></div><span class="badge">Chưa kết nối tìm kiếm AI</span>';app.querySelector('.heading').after(bar);app.querySelectorAll('.doc-icon').forEach(el=>el.innerHTML=ico('file'));app.querySelectorAll('.doc-card').forEach(el=>{const meta=document.createElement('div');meta.className='doc-metadata';meta.innerHTML=ico('book')+' Nội bộ <span>· Tài liệu mẫu</span>';el.querySelector('h3').before(meta)})};
function offerState(o,t){if(o.validUntil&&o.validUntil<t.date)return {label:'Hết hiệu lực',tone:'red'};if(o.status!=='VERIFIED')return {label:'Chưa xác minh',tone:'amber'};return {label:'Đã xác minh',tone:'green'}}
renderRates=function(){$('#route-label').textContent='Danh mục nhà cung cấp';document.title='Tripwise — Danh mục nhà cung cấp';const p=route().p,q=p.get('q')||'',service=p.get('service')||'',offer=p.get('offer')||'',t=trip(),items=state.rates.filter(r=>(!service||r.id===service)&&(r.name+' '+r.category+' '+r.offers.map(o=>o.provider).join(' ')).toLocaleLowerCase('vi').includes(q.toLocaleLowerCase('vi'))),offerCount=items.reduce((n,r)=>n+r.offers.length,0);
app.innerHTML='<div class="supplier-page">'+heading('DỮ LIỆU NHÀ CUNG CẤP','Danh mục nhà cung cấp','Quản lý và so sánh nhiều báo giá nguồn trước khi đưa vào phương án.',btn(ico('plus')+' Thêm dịch vụ','new-rate','primary'))+'<section class="supplier-guidance"><div>'+ico('info')+'<p><b>Dịch vụ mô tả nhu cầu; giá thuộc về nhà cung cấp.</b><span>Chọn một báo giá ưu tiên cho từng dịch vụ. Thay đổi tại đây không tự sửa báo giá chuyến đi.</span></p></div><a class="btn" href="#workspace?tab=quote">Mở báo giá chuyến đi '+ico('arrow')+'</a></section><section class="panel supplier-catalog"><div class="supplier-toolbar"><div>'+search('rate-search','Tìm dịch vụ hoặc nhà cung cấp...',q)+'</div><span>'+items.length+' dịch vụ · '+offerCount+' báo giá</span></div>'+(service?'<div class="catalog-back"><a href="#rates">'+ico('back')+' Xem toàn bộ danh mục</a></div>':'')+'<div class="supplier-groups">'+items.map(r=>supplierServiceGroup(r,t,offer)).join('')+'</div>'+(!items.length?'<div class="empty"><h3>Không tìm thấy dịch vụ</h3><p>Thử tên dịch vụ, nhóm hoặc nhà cung cấp khác.</p></div>':'')+'<footer class="supplier-apply"><p><b>Chuyến hiện tại: '+esc(t.name)+'</b><span>Chỉ áp dụng báo giá ưu tiên đã xác minh và còn hiệu lực đến ngày khởi hành.</span></p>'+btn('Áp dụng lựa chọn vào chuyến đi','apply-rates','primary')+'</footer></section></div>'}
function supplierServiceGroup(r,t,linkedOffer=''){return '<section class="supplier-service-group"><header><div><span class="badge">'+esc(r.category)+'</span><h2>'+esc(r.name)+'</h2><p>Đơn vị: '+esc(r.unit)+'</p></div><div class="service-group-actions"><button class="btn" data-edit-rate="'+r.id+'">'+ico('edit')+' Sửa dịch vụ</button><button class="btn" data-add-offer="'+r.id+'">'+ico('plus')+' Thêm báo giá</button></div></header><div class="table-wrap"><table class="supplier-offers"><thead><tr><th>ƯU TIÊN</th><th>NHÀ CUNG CẤP</th><th>ĐƠN GIÁ</th><th>HIỆU LỰC</th><th>TRẠNG THÁI</th><th>ĐIỀU KIỆN</th><th><span class="visually-hidden">Sửa</span></th></tr></thead><tbody>'+(r.offers.length?r.offers.map(o=>supplierOfferRow(r,o,t,linkedOffer)).join(''):'<tr><td colspan="7"><div class="empty compact">Chưa có báo giá nhà cung cấp.</div></td></tr>')+'</tbody></table></div></section>'}
function supplierOfferRow(r,o,t,linkedOffer=''){const s=offerState(o,t);return '<tr class="supplier-offer '+(o.preferred?'selected ':'')+(o.id===linkedOffer?'linked':'')+'"><td data-label="Ưu tiên"><button class="offer-choice" data-prefer-offer="'+o.id+'" data-rate-id="'+r.id+'" aria-pressed="'+Boolean(o.preferred)+'" aria-label="Chọn báo giá của '+esc(o.provider)+'" '+(s.tone!=='green'?'disabled title="Chỉ chọn báo giá đã xác minh và còn hiệu lực"':'')+'><span></span>'+(o.preferred?'Đang chọn':'Chọn')+'</button></td><td data-label="Nhà cung cấp"><strong>'+esc(o.provider)+'</strong></td><td data-label="Đơn giá"><b class="offer-price">'+money(o.price)+'</b><small>/ '+esc(r.unit)+'</small></td><td data-label="Hiệu lực">'+(o.validUntil?date(o.validUntil):'Chưa đặt')+'</td><td data-label="Trạng thái"><span class="badge '+s.tone+'">'+s.label+'</span></td><td data-label="Điều kiện"><span class="offer-terms">'+esc(o.terms||'Chưa có điều kiện')+'</span></td><td class="row-action"><button class="icon-btn" data-edit-offer="'+o.id+'" data-rate-id="'+r.id+'" aria-label="Sửa báo giá của '+esc(o.provider)+'">'+ico('edit')+'</button></td></tr>'}
function previewTrip(){
const t=trip();modal.classList.add('preview-modal');openModal('Xem trước phương án cho khách','<div class="client-preview"><div class="preview-cover"><img src="assets/seoul.jpg" alt="Seoul" '+(!/seoul|hàn quốc/i.test(t.destination)?'hidden':'')+'><div><span>IKIGAI · TRIPWISE</span><h2>'+esc(t.name)+'</h2><p>Chuẩn bị riêng cho '+esc(t.client)+'</p></div></div><div class="preview-facts"><span>'+t.days+' ngày</span><span>'+(t.adults+t.children)+' khách</span><span>Khởi hành '+date(t.date)+'</span></div><p class="preview-note">Bản xem trước minh họa · Chưa xác nhận giá hoặc dịch vụ</p><div class="preview-totals"><div><small>Chi phí dự kiến toàn đoàn</small><strong>'+money(total(t))+'</strong></div><div><small>Bình quân / khách</small><b>'+money(Math.round(total(t)/(t.adults+t.children)))+'</b></div></div>'+Array.from({length:t.days},(_,i)=>'<section class="preview-day"><h3><span>Ngày '+(i+1)+'</span>'+dayDate(t,i+1)+'</h3>'+t.activities.filter(a=>a.day===i+1).sort((a,b)=>a.start.localeCompare(b.start)).map(a=>'<div><time>'+a.start+'</time><p><b>'+esc(a.title)+'</b><small>'+esc(a.description)+'</small></p></div>').join('')+'</section>').join('')+'<div class="form-actions">'+btn('Đóng xem trước','cancel')+btn(ico('file')+' Tải phương án','export','primary')+'</div></div>');
}
modal.addEventListener('close',()=>modal.classList.remove('preview-modal'));
function sourceDetail(id){const s=demoSources.find(x=>x.id===id);if(!s)return;openModal('Thông tin nguồn dịch vụ','<div class="source-detail">'+sourceBadge(s.kind)+'<h3>'+esc(s.name)+'</h3><p>'+esc(s.detail)+'</p><dl><dt>Nguồn</dt><dd>'+esc(s.provider)+'</dd><dt>Đơn giá minh họa</dt><dd>'+(s.price===null?'Chưa xác minh':money(s.price)+' / '+esc(s.unit))+'</dd><dt>Cập nhật</dt><dd>'+esc(s.updated)+'</dd><dt>Trạng thái dịch vụ</dt><dd>Chưa kiểm tra còn chỗ</dd></dl>'+(s.url?'<a class="btn" href="'+s.url+'" target="_blank" rel="noopener noreferrer">'+ico('globe')+' Mở website nguồn</a>':'')+'<div class="notice">Dữ liệu mẫu dùng để trình diễn. Đây không phải kết quả tìm kiếm hoặc báo giá thực tế.</div></div>')}
function sourceAdd(id){
const t=trip(),s=demoSources.find(x=>x.id===id);if(!s||s.price===null||t.quote.some(r=>r.source?.id===id))return;
const existing=s.rateId?t.quote.find(r=>r.id===s.rateId):null,qty=existing?.qty??(s.unit==='người'?t.adults+t.children:s.id==='s1'?Math.ceil((t.adults+t.children)/2)*Math.max(0,t.days-1):s.id==='s2'?t.days:s.qty);
openModal(existing?'Cập nhật nguồn cho dịch vụ':'Thêm dịch vụ vào báo giá','<div class="source-detail">'+sourceBadge(s.kind)+'<h3>'+esc(s.name)+'</h3><p>Chuyến đi: <b>'+esc(t.name)+'</b></p><p>'+(existing?'Dịch vụ đã có trong báo giá. Cập nhật nguồn và đơn giá, giữ nguyên số lượng để tránh cộng trùng.':'Thêm dịch vụ vào báo giá; lịch trình được giữ nguyên. Bạn có thể chỉnh số lượng sau khi thêm.')+'</p><dl><dt>Số lượng</dt><dd>'+qty+' '+esc(s.unit)+'</dd><dt>Đơn giá mẫu</dt><dd>'+money(s.price)+'</dd><dt>Thành tiền</dt><dd>'+money(qty*s.price)+'</dd><dt>Tổng sau thay đổi</dt><dd>'+money(total(t)-(existing?existing.qty*existing.price:0)+qty*s.price)+'</dd></dl><div class="notice">Giá minh họa · chưa xác nhận dịch vụ.</div><div class="form-actions">'+btn('Hủy','cancel')+'<button class="btn primary" data-source-confirm="'+s.id+'" data-target-trip="'+t.id+'">'+(existing?'Cập nhật dịch vụ':'Thêm vào báo giá')+'</button></div></div>');
}
function applySource(id,target){
const t=trip(),s=demoSources.find(x=>x.id===id);if(t.id!==target||!s||s.price===null||t.quote.some(r=>r.source?.id===id)){closeModal();return}
let r=s.rateId?t.quote.find(x=>x.id===s.rateId):null;const source={id:s.id,kind:s.kind,provider:s.provider,url:s.url,status:'DEMO',availability:'UNCONFIRMED'};
if(r){r.price=s.price;r.source=source}else{const qty=s.unit==='người'?t.adults+t.children:s.id==='s1'?Math.ceil((t.adults+t.children)/2)*Math.max(0,t.days-1):s.id==='s2'?t.days:s.qty;t.quote.push({id:uid(),name:s.name,category:s.category,unit:s.unit,price:s.price,qty,source})}
closeModal();history.replaceState(null,'','#workspace?tab=quote');mutate(t,'Đã cập nhật dịch vụ và lưu thông tin nguồn trong báo giá.');
}
function sourcePlace(id){const s=demoSources.find(x=>x.id===id);if(!s)return;activityForm();$('#f-title').value=s.name;$('#f-location').value='Seoul Forest, Seoul';$('#f-description').value=s.detail}
function customQuoteForm(){customQuoteSaving=false;openModal('Thêm dịch vụ ngoài danh mục',form(field('name','Tên dịch vụ','','text',true)+field('provider','Nhà cung cấp','','text',true)+'<div class="field"><label for="f-category">Nhóm dịch vụ</label><select id="f-category" name="category"><option>Lưu trú</option><option>Di chuyển</option><option selected>Tham quan</option><option>Ăn uống</option><option>Khác</option></select></div>'+field('unit','Đơn vị','người')+field('qty','Số lượng',1,'number')+field('price','Đơn giá (VND)',0,'number')+'<div class="field wide"><label for="f-terms">Điều kiện / ghi chú</label><textarea id="f-terms" name="terms" placeholder="Ví dụ: đã gồm thuế, chưa xác nhận còn chỗ"></textarea></div><label class="catalog-opt-in wide"><input type="checkbox" name="saveCatalog" value="yes"><span><b>Lưu vào Danh mục nhà cung cấp</b><small>Tạo dữ liệu chưa xác minh để có thể tái sử dụng cho chuyến sau.</small></span></label>','Thêm vào báo giá'));$('#edit-form').onsubmit=e=>{e.preventDefault();saveCustomQuote(e.currentTarget)}}
function customQuoteError(message,fieldName){const formNode=$('#edit-form'),node=$('#form-error'),fieldNode=formNode?.elements.namedItem(fieldName);if(node)node.textContent=message;if(fieldNode){fieldNode.setAttribute('aria-invalid','true');fieldNode.setAttribute('aria-describedby','form-error');fieldNode.focus()}}
function saveCustomQuote(formNode){if(customQuoteSaving)return;const x=Object.fromEntries(new FormData(formNode));for(const k of ['name','provider','category','unit','terms'])x[k]=(x[k]||'').trim();x.qty=Number(x.qty);x.price=Number(x.price);if(!x.name)return customQuoteError('Nhập tên dịch vụ.','name');if(!x.provider)return customQuoteError('Nhập nhà cung cấp.','provider');if(!x.unit)return customQuoteError('Nhập đơn vị dịch vụ.','unit');if(!Number.isInteger(x.qty)||x.qty<1||x.qty>9999)return customQuoteError('Số lượng phải là số nguyên từ 1 đến 9.999.','qty');if(!Number.isInteger(x.price)||x.price<0||x.price>1e9)return customQuoteError('Đơn giá phải là số VND nguyên từ 0 đến 1 tỷ.','price');customQuoteSaving=true;const submit=formNode.querySelector('[type="submit"]');if(submit){submit.disabled=true;submit.setAttribute('aria-busy','true')}const t=trip(),beforeQuote=clone(t.quote),beforeRates=clone(state.rates),beforeRevision=t.revision,beforeStatus=t.status,manualId=uid(),saveCatalog=x.saveCatalog==='yes',rateId=saveCatalog?uid():null,offerId=saveCatalog?uid():null,sourceId=offerId||manualId,source={id:sourceId,kind:'manual',provider:x.provider,status:'UNVERIFIED',availability:'UNCONFIRMED'},snapshot={rateId,offerId,provider:x.provider,validUntil:'',terms:x.terms,status:'UNVERIFIED',manual:true};t.quote.push({id:rateId||manualId,name:x.name,category:x.category,unit:x.unit,qty:x.qty,price:x.price,source,supplierOfferSnapshot:snapshot});if(saveCatalog)state.rates.push({id:rateId,name:x.name,category:x.category,unit:x.unit,qty:x.qty,offers:[{id:offerId,provider:x.provider,price:x.price,validUntil:'',terms:x.terms,status:'UNVERIFIED',preferred:false}]});t.revision++;t.status='DRAFT';if(!save()){t.quote=beforeQuote;state.rates=beforeRates;t.revision=beforeRevision;t.status=beforeStatus;customQuoteSaving=false;if(submit){submit.disabled=false;submit.removeAttribute('aria-busy')}return customQuoteError('Không thể lưu trên thiết bị. Dữ liệu chưa được thêm.','name')}customQuoteSaving=false;closeModal();render();toast(saveCatalog?'Đã thêm dịch vụ và lưu bản chưa xác minh vào danh mục.':'Đã thêm dịch vụ ngoài danh mục vào báo giá.')}
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
if(b.dataset.action==='client-preview')previewTrip();
if(b.dataset.action==='custom-quote')customQuoteForm();
if(b.dataset.sourceFilter){sourceFilter=b.dataset.sourceFilter;render()}
if(b.dataset.action==='reset-sources'){sourceFilter='all';sourceCategory='all';sourceQuery='';render()}
if(b.dataset.action==='clear-sources'){sourceQuery='';render();$('#source-query')?.focus()}
if(b.dataset.sourceDetail)sourceDetail(b.dataset.sourceDetail);
if(b.dataset.sourceAdd)sourceAdd(b.dataset.sourceAdd);
if(b.dataset.sourcePlace)sourcePlace(b.dataset.sourcePlace);
});
$('#modal-body').addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.sourceConfirm)applySource(b.dataset.sourceConfirm,b.dataset.targetTrip)});
app.addEventListener('change',e=>{if(e.target.id==='source-category'){sourceCategory=e.target.value;render()}});
app.addEventListener('input',e=>{if(e.target.id==='source-query'){sourceQuery=e.target.value;const clear=app.querySelector('[data-action="clear-sources"]');if(clear)clear.hidden=!sourceQuery}});
app.addEventListener('submit',e=>{if(e.target.id!=='source-search-form')return;e.preventDefault();if(sourceLoading)return;sourceQuery=$('#source-query').value;sourceLoading=true;render();setTimeout(()=>{sourceLoading=false;if(route().name==='workspace')render()},450)});
