const baseApplyClick=click;
function decorateShell(){
document.body.classList.add('tripwise-refresh');
document.querySelector('.brand').innerHTML='<span class="mark">'+ico('route')+'</span><span>tripwise<small>BY IKIGAI</small></span>';
const navIcons={trips:'trip',workspace:'spark',knowledge:'book',rates:'wallet'};
document.querySelectorAll('[data-nav]').forEach(el=>{el.querySelector('i').innerHTML=ico(navIcons[el.dataset.nav]);});
document.querySelector('[data-nav="workspace"] span').textContent='Không gian tư vấn';
document.querySelector('[data-nav="rates"] span').textContent='Danh mục nhà cung cấp';
document.querySelector('.top-right small').innerHTML='<span class="live-dot"></span> Bản thử nghiệm';
document.querySelector('.profile .avatar').textContent='K';
document.querySelector('.side-bottom .demo').innerHTML=ico('spark')+' Bản mẫu tương tác';
}
decorateShell();render();


error=function(message){const node=document.querySelector('#form-error');if(!node)return;node.textContent=message;const form=node.closest('form');const fields=Array.from(form.querySelectorAll('input,textarea,select'));const field=fields.find(x=>!x.value.trim())||fields[0];if(field){field.setAttribute('aria-invalid','true');field.setAttribute('aria-describedby','form-error');field.focus()}};
app.addEventListener('input',e=>{if(e.isComposing)e.stopImmediatePropagation()},true);
app.addEventListener('compositionend',e=>e.target.dispatchEvent(new Event('input',{bubbles:true})));
app.addEventListener('click',e=>{const b=e.target.closest('[data-clear]');if(b)setTimeout(()=>document.getElementById(b.dataset.clear)?.focus(),0)});

/* Empty workspace: capture a brief before displaying itinerary and quotation. */
const builtWorkspace=renderWorkspace,normalTripForm=tripForm,normalRender=render;
let intakeDraft=null,intakePending=null;
const intakeExample={name:'Seoul — Hành trình gia đình',client:'Gia đình anh Minh',destination:'Seoul, Hàn Quốc',date:'2027-04-05',days:5,adults:4,children:2,budget:120000000,request:'Thiết kế tour Seoul 5 ngày cho 4 người lớn, 2 trẻ em. Ngân sách 120 triệu đồng, ưu tiên văn hóa, ẩm thực và có thời gian nghỉ cho trẻ nhỏ.'};
function intakeValues(t){return intakeDraft?.target===(t?.id||'new')?intakeDraft.values:t?Object.fromEntries(['name','client','destination','date','days','adults','children','budget','request'].map(k=>[k,t[k]])):{name:'',client:'',destination:'',date:'',days:5,adults:2,children:0,budget:'',request:''}}
function renderIntake(t=null){
const v=intakeValues(t),isExisting=!!t;
app.innerHTML='<div class="intake-top"><a class="back-link" href="#trips">'+ico('back')+' Chuyến đi</a><span class="badge">Chưa có phương án</span></div><div class="intake-layout"><section class="intake-main"><div class="intake-intro"><h1>Bạn muốn thiết kế<br>chuyến đi như thế nào?</h1></div><form id="intake-form" novalidate data-target="'+(t?.id||'')+'"><section class="panel intake-brief"><label for="intake-request">Mô tả chuyến đi</label><textarea id="intake-request" name="request" rows="4" placeholder="Khách muốn đi đâu, cùng ai, ngân sách bao nhiêu? Có hoạt động hoặc yêu cầu nào cần ưu tiên?">'+esc(v.request)+'</textarea><div class="intake-example"><span>Thử một yêu cầu mẫu</span><button type="button" class="btn" data-action="intake-example">'+ico('spark')+' Seoul cho gia đình</button><button type="button" class="btn" data-action="intake-template">'+ico('book')+' Chọn tour mẫu</button></div></section><section class="panel intake-fields"><div class="section-head"><div><h2>Thông tin chuyến đi</h2><p>Điền các thông tin chính để phương án bám sát nhu cầu.</p></div><span class="badge">Bước 1 / 2</span></div><div class="form-grid">'+field('name','Tên chuyến đi',v.name,'text',true)+field('client','Khách hàng',v.client)+field('destination','Điểm đến',v.destination)+field('date','Ngày khởi hành',v.date,'date')+field('days','Số ngày (1–14)',v.days,'number')+field('adults','Người lớn',v.adults,'number')+field('children','Trẻ em',v.children,'number')+field('budget','Ngân sách toàn đoàn (VND)',v.budget,'number',true)+'<div class="form-error" id="form-error" role="alert"></div></div><div class="intake-submit"><span>'+ico('info')+' Chưa có lịch trình hoặc báo giá</span><button class="btn primary" type="submit">Kiểm tra yêu cầu '+ico('arrow')+'</button></div></section></form></section><aside class="intake-aside"><section class="panel intake-guide"><div class="ai-head"><span class="ai-symbol">'+ico('spark')+'</span><div><h2>Trợ lý Tripwise</h2><span>Chuẩn bị yêu cầu cùng bạn</span></div></div><div class="intake-guide-body"><h3>Một chuyến đi phù hợp bắt đầu từ một yêu cầu rõ ràng.</h3><p>Hãy cho mình biết:</p><ul><li>Điểm đến và thời gian dự kiến</li><li>Số khách, người lớn và trẻ em</li><li>Ngân sách cho cả đoàn</li><li>Sở thích và những mốc cần giữ</li></ul><div class="intake-guide-note">Bản thử nghiệm chưa tự phân tích nội dung bằng AI. Bạn điền thông tin bên cạnh để kiểm tra yêu cầu.</div></div></section><section class="panel intake-next"><h2>Sau khi xác nhận yêu cầu</h2>'+[['book','Tham khảo kiến thức nội bộ','Tour mẫu, kinh nghiệm và quy trình'],['globe','Bổ sung nguồn dịch vụ','Đối chiếu nội bộ và thông tin bên ngoài'],['route','Xây phương án cho khách','Lịch trình, báo giá và kiểm tra']].map(([i,a,b])=>'<div>'+ico(i)+'<p><b>'+a+'</b><small>'+b+'</small></p></div>').join('')+'</section><section class="intake-unpriced">'+ico('wallet')+'<div><span>Chi phí dự kiến</span><b>Chưa có báo giá</b><p>Hiển thị sau khi thêm dịch vụ vào phương án.</p></div></section></aside></div>';
$('#intake-form').addEventListener('input',()=>{intakeDraft={target:t?.id||'new',values:Object.fromEntries(new FormData($('#intake-form')))}});
$('#intake-form').onsubmit=e=>{e.preventDefault();reviewIntake(t)};
}
function readIntake(){return Object.fromEntries(new FormData($('#intake-form')))}
function reviewIntake(t){
const x=readIntake(),required=['name','client','destination','date'];for(const k of required){if(!x[k].trim()){const labels={name:'tên chuyến đi',client:'khách hàng',destination:'điểm đến',date:'ngày khởi hành'};$('#form-error').textContent='Vui lòng nhập '+labels[k]+'.';const f=$('#f-'+k);f.setAttribute('aria-invalid','true');f.setAttribute('aria-describedby','form-error');f.focus();return}}
for(const k of ['days','adults','children','budget'])x[k]=Number(x[k]);
if(!Number.isInteger(x.days)||x.days<1||x.days>14||!Number.isInteger(x.adults)||x.adults<1||x.adults>100||!Number.isInteger(x.children)||x.children<0||x.children>20||!Number.isFinite(x.budget)||x.budget<=0||x.budget>1e12){$('#form-error').textContent='Kiểm tra số ngày (1–14), người lớn (1–100), trẻ em (0–20) và ngân sách lớn hơn 0.';$('#f-budget').focus();return}
intakePending={target:t?.id||null,values:x};const sample=/seoul|hàn quốc|han quoc/i.test(x.destination);
openModal('Kiểm tra yêu cầu chuyến đi','<div class="intake-review"><span class="badge">Bước 2 / 2 · Xác nhận yêu cầu</span><h3>'+esc(x.name)+'</h3><p>Chuẩn bị riêng cho '+esc(x.client)+'</p><dl><dt>Điểm đến</dt><dd>'+esc(x.destination)+'</dd><dt>Khởi hành</dt><dd>'+date(x.date)+'</dd><dt>Thời gian</dt><dd>'+x.days+' ngày</dd><dt>Nhóm khách</dt><dd>'+x.adults+' người lớn · '+x.children+' trẻ em</dd><dt>Ngân sách toàn đoàn</dt><dd>'+money(x.budget)+'</dd></dl><div class="request-text">'+esc(x.request||'Chưa có yêu cầu bổ sung.')+'</div><div class="notice">'+(sample?'Phương án mẫu dùng dữ liệu Seoul minh họa, chưa gọi AI hoặc xác minh giá bên ngoài.':'Bản mẫu tự động hiện hỗ trợ Seoul. Bạn có thể bắt đầu tự thiết kế cho điểm đến này.')+'</div><div class="form-actions">'+btn('Chỉnh sửa yêu cầu','cancel')+'<button class="btn" data-action="intake-manual">Bắt đầu tự thiết kế</button>'+(sample?'<button class="btn primary" data-action="intake-generate">'+ico('spark')+' Tạo phương án mẫu</button>':'')+'</div></div>');
}
function commitIntake(generateSample){
if(!intakePending)return;const p=intakePending,x=p.values;let t=p.target?state.trips.find(t=>t.id===p.target):null;if(p.target&&!t)return;
if(t){Object.assign(t,x);t.revision++;t.status='NEW'}else{t={...x,id:uid(),tags:['Theo yêu cầu'],activities:[],quote:[],versions:[],status:'NEW',revision:1,chat:''};state.trips.push(t)}
t.planningStarted=true;state.selected=t.id;day=1;save();intakePending=null;intakeDraft=null;closeModal();location.hash='workspace';render();if(generateSample)startGenerate();else toast('Đã lưu yêu cầu. Thêm hoạt động và dịch vụ để xây phương án.');
}
renderWorkspace=function(){const t=trip();if(!t.activities.length&&!t.planningStarted){renderIntake(t);return}builtWorkspace();if(!t.quote.length){const panel=app.querySelector('.budget-panel');if(panel)panel.innerHTML='<div class="intake-unpriced">'+ico('wallet')+'<div><span>Chi phí dự kiến</span><b>Chưa có báo giá</b><p>Chọn dịch vụ để bắt đầu tính chi phí.</p><a href="#workspace?tab=quote" class="btn">Mở báo giá</a></div></div>'}};
tripForm=function(edit){if(edit)return normalTripForm(true);intakeDraft=null;location.hash='intake';render()};
render=function(){if(route().name==='intake'){document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav==='workspace');a.removeAttribute('aria-current');if(a.dataset.nav==='workspace')a.setAttribute('aria-current','page')});$('#route-label').textContent='Tiếp nhận yêu cầu';document.title='Tripwise — Tiếp nhận yêu cầu';renderIntake();return}normalRender()};
app.addEventListener('click',e=>{const a=e.target.closest('button')?.dataset.action;if(a==='intake-example'){const form=$('#intake-form');if(!form)return;for(const[k,v]of Object.entries(intakeExample)){const el=form.elements.namedItem(k);if(el)el.value=v}intakeDraft={target:form.dataset.target||'new',values:readIntake()};$('#intake-request').focus()}if(a==='intake-template'){openModal('Chọn tour mẫu nội bộ','<div class="source-detail"><span class="badge">Tour mẫu nội bộ · dữ liệu minh họa</span><h3>Seoul 5 ngày cho gia đình</h3><p>Văn hóa, ẩm thực, hoạt động nhẹ và thời gian nghỉ cho trẻ nhỏ. Dùng làm điểm bắt đầu rồi điều chỉnh theo khách.</p><div class="form-actions">'+btn('Hủy','cancel')+btn('Dùng yêu cầu mẫu','intake-use-template','primary')+'</div></div>')}});
$('#modal-body').addEventListener('click',e=>{const a=e.target.closest('button')?.dataset.action;if(a==='intake-use-template'){closeModal();app.querySelector('[data-action="intake-example"]')?.click()}if(a==='intake-manual')commitIntake(false);if(a==='intake-generate')commitIntake(true)});
app.addEventListener('input',e=>{if(e.target.closest('#intake-form')){e.target.removeAttribute('aria-invalid');e.target.removeAttribute('aria-describedby')}});
render();


app.addEventListener('click',e=>{const b=e.target.closest('[data-pipeline]');if(!b)return;const p=route().p;if(b.dataset.pipeline)p.set('status',b.dataset.pipeline);else p.delete('status');location.hash='trips'+(p.size?'?'+p:'');render()});
function intakeControl(name,label,value,type='text',span=1){
const hints={name:'Ví dụ: Seoul 5 ngày cho gia đình',client:'Tên khách hàng hoặc đoàn',destination:'Thành phố hoặc quốc gia',budget:'Nhập ngân sách'},limits={days:'min="1" max="14" step="1"',adults:'min="1" max="100" step="1"',children:'min="0" max="20" step="1"',budget:'min="1" max="1000000000000" step="1000"'};
return '<div class="field trip-entry-field entry-'+name+' '+(span===2?'span-2':'')+'"><label for="f-'+name+'">'+label+'</label><div class="trip-input-shell"><input id="f-'+name+'" name="'+name+'" type="'+type+'" value="'+esc(value)+'" placeholder="'+(hints[name]||'')+'" '+(limits[name]||'')+' '+(name!=='children'?'aria-required="true"':'')+' autocomplete="'+(name==='client'?'name':'off')+'">'+(name==='budget'?'<span class="currency-unit">VND</span>':'')+'</div></div>'
}
function intakeLiveSummary(){
const form=$('#intake-form'),node=$('#intake-live');if(!form||!node)return;
const v=Object.fromEntries(new FormData(form)),adults=Number(v.adults),children=Number(v.children),days=Number(v.days),budget=Number(v.budget);
const groups=[
['pin','Điểm đến',v.destination.trim()||'Chưa chọn điểm đến',!!v.destination.trim(),'destination'],
['clock','Thời gian',v.date&&days>0?date(v.date)+' · '+days+' ngày':'Chưa chọn ngày khởi hành',!!v.date&&Number.isInteger(days)&&days>=1&&days<=14,'date'],
['trip','Nhóm khách',adults>=1?adults+' người lớn'+(children>0?' · '+children+' trẻ em':''):'Chưa nhập số khách',Number.isInteger(adults)&&adults>=1&&adults<=100&&Number.isInteger(children)&&children>=0&&children<=20,'adults'],
['wallet','Ngân sách toàn đoàn',budget>0?money(budget):'Chưa nhập ngân sách',Number.isFinite(budget)&&budget>0&&budget<=1e12,'budget'],
['file','Khách hàng',v.client.trim()||'Chưa có thông tin',!!v.name.trim()&&!!v.client.trim(),v.name.trim()?'client':'name']
];const count=groups.filter(x=>x[3]).length;
node.innerHTML='<div class="entry-summary-list">'+groups.map(([icon,label,value,done,key])=>'<button type="button" class="entry-summary-item '+(done?'is-filled':'')+'" data-intake-focus="'+key+'" title="Chỉnh sửa '+label.toLowerCase()+'"><span class="entry-summary-icon">'+ico(icon)+'</span><span class="entry-summary-text"><small>'+label+'</small><b>'+esc(value)+'</b></span>'+ico(done?'check':'edit')+'</button>').join('')+'</div><div class="entry-progress"><div><span>'+(count===5?'Sẵn sàng kiểm tra yêu cầu':'Hoàn thiện thông tin')+'</span><b>'+count+'/5</b></div><progress aria-label="Số nhóm thông tin đã điền" max="5" value="'+count+'">'+count+'/5</progress></div><div class="entry-price"><span>Chi phí dự kiến</span><strong>Chưa có báo giá</strong><p>Tính sau khi thêm dịch vụ vào lịch trình.</p></div>';
}
renderIntake=function(t=null){
const v=intakeValues(t);
app.innerHTML='<div class="intake-elegant"><header class="entry-page-heading"><div><a class="back-link" href="#trips">'+ico('back')+' Chuyến đi</a><h1>Thiết kế chuyến đi</h1></div><ol class="entry-stepper" aria-label="Các bước tạo phương án"><li aria-current="step"><span>1</span>Thông tin chuyến đi</li><li><span>2</span>Xác nhận</li></ol></header><div class="entry-layout"><form id="intake-form" class="entry-form" novalidate data-target="'+(t?.id||'')+'"><section class="entry-section"><div class="entry-section-heading"><h2>Thông tin chuyến đi</h2><button type="button" class="btn entry-template" data-action="intake-template">'+ico('book')+' Chọn tour mẫu</button></div><div class="entry-grid entry-grid-profile">'+intakeControl('name','Tên chuyến đi',v.name,'text',2)+intakeControl('client','Khách hàng',v.client,'text',2)+intakeControl('destination','Điểm đến',v.destination,'text',2)+intakeControl('date','Ngày khởi hành',v.date,'date')+intakeControl('days','Số ngày',v.days,'number')+'</div></section><section class="entry-section"><div class="entry-section-heading"><h2>Nhóm khách & ngân sách</h2></div><div class="entry-grid">'+intakeControl('adults','Người lớn',v.adults,'number')+intakeControl('children','Trẻ em',v.children,'number')+intakeControl('budget','Ngân sách toàn đoàn',v.budget,'number',2)+'</div></section><section class="entry-section entry-preferences"><div class="entry-section-heading"><h2>Yêu cầu riêng</h2><span class="optional-label">Không bắt buộc</span></div><label class="visually-hidden" for="intake-request">Mô tả chuyến đi</label><textarea id="intake-request" name="request" rows="3" placeholder="Sở thích, trải nghiệm mong muốn hoặc những lưu ý cần giữ trong hành trình...">'+esc(v.request)+'</textarea><div class="entry-example-row"><button type="button" data-action="intake-example">Thử với yêu cầu mẫu Seoul '+ico('arrow')+'</button></div></section><div class="form-error" id="form-error" role="alert"></div><footer class="entry-form-footer"><a href="#trips" class="entry-cancel">Quay lại</a><button class="btn primary" type="submit">Kiểm tra yêu cầu '+ico('arrow')+'</button></footer></form><aside class="entry-side"><section class="entry-summary"><header><h2>Tóm tắt chuyến đi</h2><span>Đang chuẩn bị</span></header><div id="intake-live"></div></section><div class="entry-help">'+ico('info')+'<p>Bạn sẽ xem lại thông tin trước khi tạo phương án.</p></div><div class="entry-demo-note">Bản thử nghiệm · chưa kết nối AI</div></aside></div></div>';
$('#intake-form').addEventListener('input',()=>{intakeDraft={target:t?.id||'new',values:readIntake()};intakeLiveSummary()});
$('#intake-form').addEventListener('change',intakeLiveSummary);
$('#intake-form').onsubmit=e=>{e.preventDefault();reviewIntake(t)};intakeLiveSummary();
};
app.addEventListener('click',e=>{if(e.target.closest('[data-action="intake-example"]'))intakeLiveSummary();const b=e.target.closest('[data-intake-focus]');if(b){const target=$('#f-'+b.dataset.intakeFocus);target?.focus();target?.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}});
render();

